SELECT order_id, CASE WHEN quantity >= 8 THEN 'high' WHEN quantity >= 4 THEN 'mid' ELSE 'low' END AS quantity_bucket, MAX(unit_price) - MIN(unit_price) AS unit_price_range FROM order_items WHERE order_id IN (2, 11, 29) OR order_id IN (23, 26) GROUP BY 1, 2 HAVING COUNT(DISTINCT quantity) >= 5 ORDER BY 2 ASC, order_id ASC LIMIT 20;
